const crypto = require('crypto');
const item = $input.item.json;
const headers = item.headers || {};
const query = item.query || {};
const body = item.body || {};

// ── Authentication (FAIL-CLOSED) ──────────────────────────────────────────────
// configuredSecret is REQUIRED. No secret configured = deny all API requests.
const configuredSecret = $env.DASHBOARD_SECRET || $env.DASHBOARD_API_KEY || '';

const rawAuthHeader = headers['authorization'] || headers['Authorization'] || '';
const bearerSecret = rawAuthHeader ? rawAuthHeader.replace(/^Bearer\s+/i, '').trim() : '';
const customHeaderSecret = headers['x-dashboard-secret'] || headers['X-Dashboard-Secret'] || '';
const clientSecret = bearerSecret || customHeaderSecret;

const actor = headers['x-dashboard-actor'] || headers['X-Dashboard-Actor'] || headers['x-dashboard-user'] || 'receptionist';

let isAuthorized = false;

// Constant-time comparison only when both sides are non-empty strings
if (configuredSecret && clientSecret) {
  try {
    const bufA = Buffer.from(configuredSecret, 'utf8');
    const bufB = Buffer.from(clientSecret, 'utf8');
    if (bufA.length === bufB.length && crypto.timingSafeEqual(bufA, bufB)) {
      isAuthorized = true;
    }
  } catch (e) {
    isAuthorized = false;
  }
}
// NOTE: If configuredSecret is missing OR clientSecret is missing, isAuthorized remains false.
// There is NO development bypass. Missing config = denied.

// ── Action routing ────────────────────────────────────────────────────────────
let action = 'SERVE_HTML';
if (body.action) {
  action = body.action;
} else if (query.action) {
  action = query.action;
}

const allowedActions = [
  'SERVE_HTML',
  'GET_APPOINTMENTS',
  'GET_DOCTORS',
  'CREATE_APPOINTMENT',
  'UPDATE_STATUS',
  'RESCHEDULE_APPOINTMENT',
  'CANCEL_APPOINTMENT',
  'SET_DOCTOR_LEAVE'
];

// ── Enforce auth on all non-HTML actions ─────────────────────────────────────
let error = null;
if (action === 'SERVE_HTML') {
  // Public: serve the SPA shell without authentication
} else if (!isAuthorized) {
  action = 'UNAUTHORIZED';
  error = 'Unauthorized: missing or invalid dashboard authentication credential';
} else if (!allowedActions.includes(action)) {
  action = 'INVALID_ACTION';
  error = 'Invalid action: ' + action;
}

return [{
  json: {
    action: action,
    payload: body,
    query: query,
    actor: actor,
    error: error,
    is_authorized: isAuthorized,
    received_at: new Date().toISOString()
  }
}];

const clinicName = $env.CLINIC_NAME || 'Apex Healthcare Clinic';
const clinicTimezone = $env.CLINIC_TIMEZONE || 'Asia/Kolkata';

const html = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${clinicName} - Reception Dashboard</title>
  <link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css" rel="stylesheet">
  <link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css" rel="stylesheet">
