    #auth-overlay { position: fixed; inset: 0; background: rgba(15,23,42,0.85); backdrop-filter: blur(4px); z-index: 9999; display: none; align-items: center; justify-content: center; }
  </style>
</head>
<body>
  <!-- Auth Modal Overlay -->
  <div id="auth-overlay">
    <div class="card p-4 shadow-lg border-0" style="max-width: 420px; width: 100%; border-radius: 16px;">
      <div class="text-center mb-3">
        <i class="fa-solid fa-shield-halved fa-2x text-primary mb-2"></i>
        <h4 class="fw-bold">Staff Access</h4>
        <p class="text-muted small">Enter your dashboard access secret to authenticate.</p>
      </div>
      <div class="mb-3">
        <label class="form-label small fw-semibold">Receptionist / User ID</label>
        <input type="text" class="form-control" id="auth-user" placeholder="reception_1">
      </div>
      <div class="mb-3">
        <label class="form-label small fw-semibold">Dashboard Secret</label>
        <input type="password" class="form-control" id="auth-secret" placeholder="••••••••">
      </div>
      <button class="btn btn-primary w-100 py-2 fw-semibold" id="btn-login" onclick="handleLogin()">Sign In</button>
      <div id="auth-error" class="text-danger small mt-2 text-center" style="display: none;"></div>
    </div>
  </div>

  <nav class="navbar navbar-expand-lg navbar-custom px-4 py-3">
    <div class="container-fluid">
      <span class="navbar-brand text-white fw-bold"><i class="fa-solid fa-hospital-user me-2 text-primary"></i>${clinicName} - Reception Desk</span>
      <div class="d-flex align-items-center gap-2">
        <button class="btn btn-primary btn-sm" id="btn-new-appt" onclick="openNewModal()"><i class="fa-solid fa-plus me-1"></i> New Appointment</button>
        <button class="btn btn-outline-light btn-sm" id="btn-doc-leave" onclick="openLeaveModal()"><i class="fa-solid fa-user-clock me-1"></i> Doctor Leave</button>
        <button class="btn btn-secondary btn-sm" id="btn-refresh" onclick="loadAppointments()"><i class="fa-solid fa-rotate me-1"></i> Refresh</button>
        <button class="btn btn-outline-danger btn-sm" onclick="handleLogout()"><i class="fa-solid fa-right-from-bracket"></i></button>
      </div>
    </div>
  </nav>

  <div class="container-fluid px-4 py-4">
    <!-- Stat Cards -->
    <div class="row g-3 mb-4">
      <div class="col-md-3">
        <div class="card card-stat bg-white p-3">
          <div class="d-flex justify-content-between align-items-center">
            <div>
              <span class="text-muted small">Today's Schedule</span>
              <h3 class="fw-bold mt-1 mb-0" id="stat-today">0</h3>
            </div>
            <div class="bg-primary-subtle text-primary p-3 rounded-circle"><i class="fa-solid fa-calendar-day fa-lg"></i></div>
          </div>
        </div>
      </div>
      <div class="col-md-3">
        <div class="card card-stat bg-white p-3">
          <div class="d-flex justify-content-between align-items-center">
            <div>
              <span class="text-muted small">Confirmed</span>
              <h3 class="fw-bold mt-1 mb-0 text-primary" id="stat-confirmed">0</h3>
            </div>
            <div class="bg-info-subtle text-info p-3 rounded-circle"><i class="fa-solid fa-check fa-lg"></i></div>
          </div>
        </div>
      </div>
      <div class="col-md-3">
        <div class="card card-stat bg-white p-3">
          <div class="d-flex justify-content-between align-items-center">
            <div>
              <span class="text-muted small">Arrived / In Clinic</span>
              <h3 class="fw-bold mt-1 mb-0 text-indigo" id="stat-arrived">0</h3>
            </div>
            <div class="bg-warning-subtle text-warning p-3 rounded-circle"><i class="fa-solid fa-door-open fa-lg"></i></div>
          </div>
        </div>
      </div>
      <div class="col-md-3">
        <div class="card card-stat bg-white p-3">
          <div class="d-flex justify-content-between align-items-center">
            <div>
              <span class="text-muted small">Completed Today</span>
              <h3 class="fw-bold mt-1 mb-0 text-success" id="stat-completed">0</h3>
            </div>
            <div class="bg-success-subtle text-success p-3 rounded-circle"><i class="fa-solid fa-circle-check fa-lg"></i></div>
          </div>
        </div>
      </div>
    </div>

    <!-- Filters, Search, Pagination -->
    <div class="d-flex justify-content-between align-items-center mb-3 flex-wrap gap-2">
      <div class="btn-group" role="group">
        <button type="button" class="btn btn-outline-primary active" id="filter-today" onclick="setFilter('today')">Today's Schedule</button>
        <button type="button" class="btn btn-outline-primary" id="filter-upcoming" onclick="setFilter('upcoming')">Upcoming</button>
        <button type="button" class="btn btn-outline-primary" id="filter-all" onclick="setFilter('all')">All Bookings</button>
      </div>
      <div class="d-flex gap-2">
        <select class="form-select form-select-sm" id="doctor-filter" onchange="applyFilters()">
          <option value="">All Doctors</option>
        </select>
        <input type="text" class="form-control form-control-sm" id="search-box" placeholder="Search patient or phone..." oninput="applyFilters()">
      </div>
    </div>

    <!-- Table -->
    <div class="table-responsive">
      <table class="table table-hover align-middle mb-0">
        <thead class="table-light">
          <tr>
            <th>ID</th>
            <th>Patient Name</th>
            <th>Phone</th>
            <th>Doctor</th>
            <th>Service</th>
            <th>Date & Time</th>
            <th>Status</th>
            <th class="text-end">Reception Actions</th>
          </tr>
        </thead>
        <tbody id="appointment-tbody">
          <tr><td colspan="8" class="text-center py-4 text-muted">Loading appointments...</td></tr>
        </tbody>
      </table>
      <div class="d-flex justify-content-between align-items-center mt-3" id="pagination-controls">
        <span class="text-muted small" id="page-info">Showing active records</span>
      </div>
    </div>
  </div>

  <!-- Modals -->
  <div class="modal fade" id="newApptModal" tabindex="-1">
    <div class="modal-dialog">
      <div class="modal-content">
        <div class="modal-header"><h5 class="modal-title fw-bold">Create Appointment</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div>
        <div class="modal-body">
          <form id="newApptForm">
            <div class="mb-3"><label class="form-label">Patient Name</label><input type="text" class="form-control" id="m-name" required></div>
            <div class="mb-3"><label class="form-label">Phone Number</label><input type="tel" class="form-control" id="m-phone" required placeholder="919876543210"></div>
            <div class="mb-3"><label class="form-label">Doctor</label><select class="form-select" id="m-doctor" required></select></div>
            <div class="mb-3"><label class="form-label">Service</label><input type="text" class="form-control" id="m-service" value="General Consultation" required></div>
            <div class="row g-2 mb-3">
              <div class="col-6"><label class="form-label">Date</label><input type="date" class="form-control" id="m-date" required></div>
              <div class="col-6"><label class="form-label">Time</label><input type="time" class="form-control" id="m-time" required></div>
            </div>
          </form>
        </div>
        <div class="modal-footer"><button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Cancel</button><button type="button" class="btn btn-primary" id="btn-submit-new" onclick="submitNewAppointment()">Confirm & Book</button></div>
      </div>
    </div>
  </div>

  <div class="modal fade" id="reschedModal" tabindex="-1">
    <div class="modal-dialog">
      <div class="modal-content">
        <div class="modal-header"><h5 class="modal-title fw-bold">Reschedule Appointment</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div>
        <div class="modal-body">
          <input type="hidden" id="r-id">
          <p class="text-muted small mb-3">Rescheduling appointment for <strong id="r-patient"></strong>.</p>
          <div class="row g-2 mb-3">
            <div class="col-6"><label class="form-label">New Date</label><input type="date" class="form-control" id="r-date" required></div>
            <div class="col-6"><label class="form-label">New Time</label><input type="time" class="form-control" id="r-time" required></div>
          </div>
        </div>
        <div class="modal-footer"><button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Cancel</button><button type="button" class="btn btn-warning" id="btn-submit-resched" onclick="submitReschedule()">Save Changes</button></div>
      </div>
    </div>
  </div>

  <div class="modal fade" id="leaveModal" tabindex="-1">
    <div class="modal-dialog">
      <div class="modal-content">
        <div class="modal-header"><h5 class="modal-title fw-bold">Record Doctor Unavailability / Leave</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div>
        <div class="modal-body">
          <div class="mb-3"><label class="form-label">Doctor</label><select class="form-select" id="l-doctor" required></select></div>
          <div class="mb-3"><label class="form-label">Start Time</label><input type="datetime-local" class="form-control" id="l-start" required></div>
          <div class="mb-3"><label class="form-label">End Time</label><input type="datetime-local" class="form-control" id="l-end" required></div>
          <div class="mb-3"><label class="form-label">Reason</label><input type="text" class="form-control" id="l-reason" value="Annual Leave" required></div>
        </div>
        <div class="modal-footer"><button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Cancel</button><button type="button" class="btn btn-danger" id="btn-submit-leave" onclick="submitDoctorLeave()">Record Leave</button></div>
      </div>
    </div>
  </div>

  <script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/js/bootstrap.bundle.min.js"></script>
  <script>
    const apiUrl = window.location.pathname;
    const defaultClinicTz = "${clinicTimezone}";
    let allAppointments = [];
    let allDoctors = [];
    let currentFilter = 'today';

    function getAuthSecret() { return sessionStorage.getItem('apex_dashboard_secret') || ''; }
    function getAuthActor() { return sessionStorage.getItem('apex_dashboard_actor') || 'receptionist'; }

    function checkAuth() {
      if (!getAuthSecret()) {
        document.getElementById('auth-overlay').style.display = 'flex';
      } else {
        document.getElementById('auth-overlay').style.display = 'none';
      }
    }

    function handleLogin() {
      const sec = document.getElementById('auth-secret').value.trim();
      const user = document.getElementById('auth-user').value.trim() || 'receptionist';
      if (!sec) return alert('Please enter dashboard secret');
      sessionStorage.setItem('apex_dashboard_secret', sec);
      sessionStorage.setItem('apex_dashboard_actor', user);
      document.getElementById('auth-overlay').style.display = 'none';
      loadDoctors();
      loadAppointments();
    }

    function handleLogout() {
      sessionStorage.removeItem('apex_dashboard_secret');
      sessionStorage.removeItem('apex_dashboard_actor');
      checkAuth();
    }

    function getHeaders() {
      return {
        'Content-Type': 'application/json',
        'x-dashboard-secret': getAuthSecret(),
        'x-dashboard-actor': getAuthActor()
      };
    }

    function escapeHtml(str) {
      if (!str) return '';
      return String(str)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#039;');
    }

    async function loadDoctors() {
      try {
        const res = await fetch(apiUrl, {
          method: 'POST',
          headers: getHeaders(),
          body: JSON.stringify({ action: 'GET_DOCTORS' })
        });
        if (res.status === 401) { checkAuth(); return; }
        const data = await res.json();
        if (data.success && data.data?.doctors) {
          allDoctors = data.data.doctors;
          populateDoctorDropdowns();
        }
      } catch (err) {
        console.error('Failed to load doctors:', err);
      }
    }

    function populateDoctorDropdowns() {
      const filterSel = document.getElementById('doctor-filter');
      const modalSel = document.getElementById('m-doctor');
      const leaveSel = document.getElementById('l-doctor');

      filterSel.innerHTML = '<option value="">All Doctors</option>' + 
        allDoctors.map(d => '<option value="' + escapeHtml(d.doctor_id) + '">' + escapeHtml(d.doctor_name) + ' (' + escapeHtml(d.specialty) + ')</option>').join('');

      const docOptions = allDoctors.map(d => '<option value="' + escapeHtml(d.doctor_id) + '">' + escapeHtml(d.doctor_name) + ' (' + escapeHtml(d.specialty) + ')</option>').join('');
      modalSel.innerHTML = docOptions;
      leaveSel.innerHTML = docOptions;
    }

    async function loadAppointments() {
      try {
        const res = await fetch(apiUrl, {
          method: 'POST',
          headers: getHeaders(),
          body: JSON.stringify({ action: 'GET_APPOINTMENTS', page: 1, page_size: 500 })
        });

        if (res.status === 401) {
          checkAuth();
          return;
        }

        const data = await res.json();
        if (!data.success) throw new Error(data.error?.message || data.error || 'Failed to load appointments');

        allAppointments = data.data?.appointments || [];
        updateStats();
        applyFilters();
      } catch (err) {
        document.getElementById('appointment-tbody').innerHTML = '<tr><td colspan="8" class="text-center py-4 text-danger"><i class="fa-solid fa-triangle-exclamation me-2"></i>' + escapeHtml(err.message) + '</td></tr>';
      }
    }

    function updateStats() {
      const now = new Date();
      const todayStr = new Intl.DateTimeFormat('en-CA', { timeZone: defaultClinicTz }).format(now);

      let todayCount = 0, confCount = 0, arrCount = 0, compCount = 0;

      allAppointments.forEach(a => {
        const tz = a.timezone || defaultClinicTz;
        const apptDateStr = new Intl.DateTimeFormat('en-CA', { timeZone: tz }).format(new Date(a.start_time));
        const isToday = (apptDateStr === todayStr);

        if (isToday) todayCount++;
        if (a.status === 'CONFIRMED' || a.status === 'RESCHEDULED') confCount++;
        if (a.status === 'ARRIVED') arrCount++;
        if (isToday && a.status === 'COMPLETED') compCount++;
      });

      document.getElementById('stat-today').innerText = todayCount;
      document.getElementById('stat-confirmed').innerText = confCount;
      document.getElementById('stat-arrived').innerText = arrCount;
      document.getElementById('stat-completed').innerText = compCount;
    }

    function setFilter(f) {
      currentFilter = f;
      ['today', 'upcoming', 'all'].forEach(k => {
        document.getElementById('filter-' + k).classList.toggle('active', k === f);
      });
      applyFilters();
    }

    function applyFilters() {
      const query = document.getElementById('search-box').value.toLowerCase();
      const doctorFilter = document.getElementById('doctor-filter').value;
      const now = new Date();
      const todayStr = new Intl.DateTimeFormat('en-CA', { timeZone: defaultClinicTz }).format(now);

      const filtered = allAppointments.filter(a => {
        const tz = a.timezone || defaultClinicTz;
        const aDate = new Date(a.start_time);
        const aDateStr = new Intl.DateTimeFormat('en-CA', { timeZone: tz }).format(aDate);

        if (currentFilter === 'today' && aDateStr !== todayStr) return false;
        if (currentFilter === 'upcoming' && (aDate <= now || ['CANCELLED', 'COMPLETED', 'EXPIRED'].includes(a.status))) return false;
        if (doctorFilter && a.doctor_id !== doctorFilter) return false;
        if (query) {
          const matchName = (a.customer_name || '').toLowerCase().includes(query);
          const matchPhone = (a.phone || '').includes(query);
          const matchId = String(a.appointment_id).includes(query);
          if (!matchName && !matchPhone && !matchId) return false;
        }
        return true;
      });

      renderTable(filtered);
    }

    function renderTable(list) {
      const tbody = document.getElementById('appointment-tbody');
      if (list.length === 0) {
        tbody.innerHTML = '<tr><td colspan="8" class="text-center py-4 text-muted">No appointments found matching current filter.</td></tr>';
        return;
      }

      tbody.innerHTML = list.map(a => {
        const tz = a.timezone || defaultClinicTz;
        const dt = new Date(a.start_time);
        const formattedDate = new Intl.DateTimeFormat('en-US', { timeZone: tz, month: 'short', day: 'numeric', year: 'numeric' }).format(dt);
        const formattedTime = new Intl.DateTimeFormat('en-US', { timeZone: tz, hour: '2-digit', minute: '2-digit' }).format(dt);
        const safeId = Number(a.appointment_id);
        const cleanPhone = encodeURIComponent(String(a.phone || ''));

        return \`
          <tr>
            <td><span class="text-muted fw-bold">#\${safeId}</span></td>
            <td class="fw-semibold">\${escapeHtml(a.customer_name)}</td>
            <td><a href="https://wa.me/\${cleanPhone}" target="_blank" class="text-decoration-none"><i class="fa-brands fa-whatsapp text-success me-1"></i>\${escapeHtml(a.phone)}</a></td>
            <td><span class="badge bg-light text-dark border">\${escapeHtml(a.doctor_name || a.doctor_id)}</span></td>
            <td>\${escapeHtml(a.service)}</td>
            <td><strong>\${escapeHtml(formattedDate)}</strong> <span class="text-muted">\${escapeHtml(formattedTime)}</span></td>
            <td><span class="badge badge-status status-\${escapeHtml(a.status)}">\${escapeHtml(a.status)}</span></td>
            <td class="text-end">
              <div class="dropdown d-inline-block">
                <button class="btn btn-sm btn-light border dropdown-toggle" data-bs-toggle="dropdown">Actions</button>
                <ul class="dropdown-menu dropdown-menu-end">
                  <li><a class="dropdown-item text-primary" href="#" onclick="updateStatus(\${safeId}, 'ARRIVED')"><i class="fa-solid fa-door-open me-2"></i>Mark Arrived</a></li>
                  <li><a class="dropdown-item text-success" href="#" onclick="updateStatus(\${safeId}, 'COMPLETED')"><i class="fa-solid fa-check-double me-2"></i>Mark Completed</a></li>
                  <li><a class="dropdown-item text-secondary" href="#" onclick="updateStatus(\${safeId}, 'NO_SHOW')"><i class="fa-solid fa-user-slash me-2"></i>Mark No-Show</a></li>
                  <li><hr class="dropdown-divider"></li>
                  <li><a class="dropdown-item text-warning" href="#" onclick="openReschedModal(\${safeId})"><i class="fa-solid fa-calendar-days me-2"></i>Reschedule</a></li>
                  <li><a class="dropdown-item text-danger" href="#" onclick="cancelAppt(\${safeId})"><i class="fa-solid fa-trash me-2"></i>Cancel</a></li>
                </ul>
              </div>
            </td>
          </tr>
        \`;
      }).join('');
    }

    async function updateStatus(id, newStatus) {
      if (!confirm('Update appointment #' + id + ' status to ' + newStatus + '?')) return;
      try {
        const res = await fetch(apiUrl, {
          method: 'POST',
          headers: getHeaders(),
          body: JSON.stringify({ action: 'UPDATE_STATUS', appointment_id: id, status: newStatus })
        });
        const data = await res.json();
        if (!res.ok || data.success === false) {
          throw new Error(data.error?.message || data.error || 'Status update failed');
        }
        loadAppointments();
      } catch (err) {
        alert('Action failed: ' + err.message);
      }
    }

    async function cancelAppt(id) {
      if (!confirm('Cancel appointment #' + id + '?')) return;
      try {
        const res = await fetch(apiUrl, {
          method: 'POST',
          headers: getHeaders(),
          body: JSON.stringify({ action: 'CANCEL_APPOINTMENT', appointment_id: id })
        });
        const data = await res.json();
        if (!res.ok || data.success === false) {
          throw new Error(data.error?.message || data.error || 'Cancellation failed');
        }
